(33009, 'Numbers 17:5', 'Numbers', 17, 5, 'بیا به د هغه کس امسا غوټۍ ونیسي چې زه یې غوره کوم. په دې ډول به ستاسو په خلاف د دغو اسراییلیانو دوامداره شکایتونو ته د پای ټکی کېږدم.»', 'بیا به د هغه کس امسا غوتی ونیسی چې زه یې غوره کوم. په دې دول به ستاسو په خلاف د دغو اسراییلیانو دوامداره شکایتونو ته د پای تکی کېزدم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33010, 'Numbers 17:6', 'Numbers', 17, 6, 'موسی د اسراییلیانو سره خبرې وکړې او د هغوی هر یو مشر موسی ته امسا ورکړه، یعنې د هرې قبیلې څخه یوه یوه دانه چې ټولې دولس وې او د هارون امسا هم په کې شامله وه.', 'موسی د اسراییلیانو سره خبرې وکرې او د هغوی هر یو مشر موسی ته امسا ورکره، یعنې د هرې قبیلې چخه یوه یوه دانه چې تولې دولس وې او د هارون امسا هم په کې شامله وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33011, 'Numbers 17:7', 'Numbers', 17, 7, 'بیا موسی ټولې امساګانې په خېمه کې د څښتن د لوظ د صندوق مخې ته کېښودلې.', 'بیا موسی تولې امساګانې په خېمه کې د چشتن د لوظ د صندوق مخې ته کېشودلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33012, 'Numbers 17:8', 'Numbers', 17, 8, 'په سبا ورځ کله چې موسی خېمې ته ورننوت، هغه ولیدل چې د هارون امسا چې د لاوي د قبیلې استازیتوب یې کوله تېغ وهلی. هغې غوټۍ کړې وې، ګلان یې نیولي وو او بادام یې کړي وو!', 'په سبا ورج کله چې موسی خېمې ته ورننوت، هغه ولیدل چې د هارون امسا چې د لاوی د قبیلې استازیتوب یې کوله تېغ وهلی. هغې غوتی کرې وې، ګلان یې نیولی وو او بادام یې کری وو!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33013, 'Numbers 17:9', 'Numbers', 17, 9, 'موسی هغه دولس امساګانې له خېمې څخه راوویستلې او خلکو ته یې ورښکاره کړې. هر مشر خپله امسا راپیدا کړه او هغه یې واخیستله.', 'موسی هغه دولس امساګانې له خېمې چخه راوویستلې او خلکو ته یې ورشکاره کرې. هر مشر خپله امسا راپیدا کره او هغه یې واخیستله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33014, 'Numbers 17:10', 'Numbers', 17, 10, 'خو څښتن موسی ته وویل: «د هارون امسا بېرته د لوظ صندوق ته مخامخ کېږده! پرېږده چې هغه هلته پاتې وي او د هغه چا دپاره چې د سرکښۍ کولو په اړه فکر کوي د خبرداري په توګه وي. که چېرې دا خلک زما په هکله شکایت بس نه کړي، نو زه به یې له منځه یوسم.»', 'خو چشتن موسی ته وویل: «د هارون امسا بېرته د لوظ صندوق ته مخامخ کېزده! پرېزده چې هغه هلته پاتې وی او د هغه چا دپاره چې د سرکشی کولو په اره فکر کوی د خبرداری په توګه وی. که چېرې دا خلک زما په هکله شکایت بس نه کری، نو زه به یې له منجه یوسم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33015, 'Numbers 17:11', 'Numbers', 17, 11, 'لکه څنګه چې څښتن حکم کړی ؤ، موسی هماغسې وکړل.', 'لکه چنګه چې چشتن حکم کری و، موسی هماغسې وکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33016, 'Numbers 17:12', 'Numbers', 17, 12, 'اسراییلیانو موسی ته فریاد وکړ او ویې ویل: «مونږ مړه کېږو! زمونږ دپاره کومه هیله نشته، مونږ ټول له منځه ځو!', 'اسراییلیانو موسی ته فریاد وکر او ویې ویل: «مونز مره کېزو! زمونز دپاره کومه هیله نشته، مونز تول له منجه جو!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_17_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
